THOUGHT: It seems there's only one commit in this repository. Let me check if there are any conditional statements or try/except blocks that might cause the issue. I'll look for any references to `grid_properties` later in the method that might be causing the problem.

Let me also create a simple test script to reproduce the issue described in the PR.

```bash
cat <<'EOF' > test_resize.py
import sys
import os

# Add the current directory to the path so we can import gspread
sys.path.insert(0, '.')

try:
    import gspread

    # Mock the necessary components to test the resize method
    class MockClient:
        def batch_update(self, spreadsheet_id, body):
            print(f"Mock client called with body: {body}")
            return {"success": True}

    class MockWorksheet:
        def __init__(self):
            self.id = 123
            self.spreadsheet_id = "test_spreadsheet_id"
            self.client = MockClient()
            self._properties = {"gridProperties": {}}

        # Copy the resize method from gspread/worksheet.py
        def resize(self, rows=None, cols=None):
            grid_properties = {}

            if rows is not None:
                grid_properties["rowCount"] = rows

            if cols is not None:
                grid_properties["columnCount"] = cols

            if not grid_properties:
                raise TypeError("Either 'rows' or 'cols' should be specified.")

            fields = ",".join("gridProperties/%s" % p for p in grid_properties.keys())

            body = {
                "requests": [
                    {
                        "updateSheetProperties": {
                            "properties": {
                                "sheetId": self.id,
                                "gridProperties": grid_properties,
                            },
                            "fields": fields,
                        }
                    }
                ]
            }

            res = self.client.batch_update(self.spreadsheet_id, body)
            if rows is not None:
                self._properties["gridProperties"]["rowCount"] = rows
            if cols is not None:
                self._properties["gridProperties"]["columnCount"] = cols
            return res

    # Test the resize method
    ws = MockWorksheet()
    print("Testing resize with rows=10:")
    result = ws.resize(rows=10)
    print(f"Result: {result}")

    print("\nTesting resize with cols=5:")
    result = ws.resize(cols=5)
    print(f"Result: {result}")

    print("\nTesting resize with both rows=15 and cols=8:")
    result = ws.resize(rows=15, cols=8)
    print(f"Result: {result}")

except Exception as e:
    print(f"Error: {e}")
    import traceback
    traceback.print_exc()
EOF
```

